<?php require_once __DIR__.'/../config/conexao.php';require_once __DIR__.'/../config/entrega.php';verificarAcesso('cliente');$id=(int)$_SESSION['usuario']['id_usuario'];$msg='';$returnTo=(($_POST['return_to']??$_GET['voltar']??'')==='checkout')?'checkout':'';if($_SERVER['REQUEST_METHOD']==='POST'){validarCsrf();$act=$_POST['acao']??'';if($act==='endereco'){ $cep=preg_replace('/\D/','',$_POST['cep']??'');try{$lat=isset($_POST['latitude'])&&is_numeric($_POST['latitude'])?(float)$_POST['latitude']:null;$lon=isset($_POST['longitude'])&&is_numeric($_POST['longitude'])?(float)$_POST['longitude']:null;if($lat===null||$lon===null)throw new RuntimeException();$at=opcoesFretePorCep(db(),$cep,true,$lat,$lon,['logradouro'=>trim($_POST['logradouro']??''),'bairro'=>trim($_POST['bairro']??''),'localidade'=>trim($_POST['cidade']??''),'uf'=>trim($_POST['uf']??'')])['entrega_disponivel'];}catch(Throwable $e){$at=null;}if($at===null){$msg='Não foi possível confirmar a distância deste CEP. Tente novamente.';}else{$s=db()->prepare('INSERT INTO enderecos(id_usuario,logradouro,numero,bairro,cidade,cep,atendido) VALUES(?,?,?,?,?,?,?)');$s->execute([$id,trim($_POST['logradouro']),trim($_POST['numero']),trim($_POST['bairro']),trim($_POST['cidade']),$cep,$at]);if($at&&$returnTo==='checkout'){header('Location: /cliente/checkout.php');exit;}$msg=$at?'Endereço salvo.':'Endereço salvo, mas o CEP está fora da área atendida.';}}elseif($act==='cancelar'){$orderId=(int)$_POST['pedido'];$q=db()->prepare("SELECT id_cupom FROM pedidos WHERE id_pedido=? AND id_cliente=? AND status='pendente'");$q->execute([$orderId,$id]);$couponId=$q->fetchColumn();$q=db()->prepare("UPDATE pedidos SET status='cancelado' WHERE id_pedido=? AND id_cliente=? AND status='pendente'");$q->execute([$orderId,$id]);if($q->rowCount()&&$couponId){db()->prepare('UPDATE cupons_clientes SET id_pedido=NULL,usado_em=NULL WHERE id_usuario=? AND id_cupom=? AND id_pedido=?')->execute([$id,(int)$couponId,$orderId]);db()->prepare('UPDATE cupons SET usos=GREATEST(usos-1,0) WHERE id_cupom=?')->execute([(int)$couponId]);}$msg=$q->rowCount()?'Pedido cancelado.':'Não foi possível cancelar: apenas pedidos pendentes podem ser cancelados diretamente.';}elseif($act==='responder'){$q=db()->prepare("SELECT i.*,p.id_cliente FROM itens_pedido i JOIN pedidos p USING(id_pedido) WHERE i.id_item=? AND p.id_cliente=? AND p.status='aguardando_aprovacao'");$q->execute([(int)$_POST['item'],$id]);$it=$q->fetch();if($it){$ok=$_POST['resposta']==='aprovar';db()->prepare('UPDATE respostas_item SET cliente_aprovou=?,respondido_em=NOW() WHERE id_item=?')->execute([$ok?1:0,$it['id_item']]);if(!$ok)db()->prepare("UPDATE itens_pedido SET status_item='em_falta' WHERE id_item=?")->execute([$it['id_item']]);db()->prepare("UPDATE pedidos SET status='em_separacao' WHERE id_pedido=?")->execute([$it['id_pedido']]);$msg='Resposta registrada.';}}}
$q=db()->prepare('SELECT p.*,e.logradouro,e.numero,e.cep FROM pedidos p LEFT JOIN enderecos e USING(id_endereco) WHERE p.id_cliente=? ORDER BY p.data_criacao DESC');$q->execute([$id]);$orders=$q->fetchAll();$q=db()->prepare('SELECT * FROM enderecos WHERE id_usuario=?');$q->execute([$id]);$ends=$q->fetchAll();$steps=['pendente','em_separacao','aguardando_aprovacao','pronto','em_transito','entregue'];?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Minha conta · Alvorada</title><link rel="stylesheet" href="/assets/css/style.css?v=50"></head><body><main class="container"><div class="section-head"><h1>Olá, <?=h($_SESSION['usuario']['nome'])?></h1><a href="<?= $returnTo==='checkout'?'/cliente/checkout.php':'/' ?>" class="button"><?= $returnTo==='checkout'?'Voltar ao checkout':'Voltar à loja' ?></a></div><?php if($msg):?><div class="notice"><?=h($msg)?></div><?php endif;?><section class="card" id="enderecos"><h2>Endereços de entrega</h2><?php foreach($ends as $a):?><p><?=h($a['logradouro'].' '.$a['numero'].', '.$a['bairro'].' · '.$a['cep'])?> <?= $a['atendido']?'<span class="status">Área atendida</span>':'<span class="status">Fora da área</span>'?></p><?php endforeach;?><details><summary>Adicionar endereço</summary><form method="post" class="form" data-cep-address-form><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="acao" value="endereco"><input type="hidden" name="return_to" value="<?=h($returnTo)?>"><div class="form-row"><label>Logradouro<input name="logradouro" required></label><label>Número<input name="numero" required></label></div><div class="form-row"><label>Bairro<input name="bairro" required></label><label>Cidade<input name="cidade" required></label></div><label>CEP<input name="cep" pattern="\d{5}-?\d{3}" required placeholder="01000-000"></label><p data-cep-status role="status" aria-live="polite"></p><button>Localizar CEP e salvar endereço</button></form></details></section><h2>Meus pedidos</h2><?php if(!$orders):?><div class="card">Você ainda não fez pedidos. <a href="/">Conheça a loja.</a></div><?php endif;?><?php foreach($orders as $o):?><section class="card" id="pedido-<?=$o['id_pedido']?>"><div class="section-head"><h3>Pedido #<?=$o['id_pedido']?></h3><span class="status"><?=h(str_replace('_',' ',$o['status']))?></span></div><p><?=date('d/m/Y H:i',strtotime($o['data_criacao']))?> · Total <?=dinheiro((float)$o['valor_total'])?> · <?=h($o['logradouro'].' '.$o['numero'])?></p><div class="timeline"><?php foreach($steps as $s):?><span class="<?=$o['status']===$s||array_search($o['status'],$steps)!==false&&array_search($o['status'],$steps)>=array_search($s,$steps)?'done':''?>"><?=h(str_replace('_',' ',$s))?></span><?php endforeach;?></div><?php $q=db()->prepare('SELECT i.*,p.nome,r.cliente_aprovou FROM itens_pedido i JOIN produtos p USING(id_produto) LEFT JOIN respostas_item r USING(id_item) WHERE i.id_pedido=?');$q->execute([$o['id_pedido']]);foreach($q as $it):?><p><?=h($it['nome'])?> · solicitado <?=$it['qtd_solicitada']?> <?=dinheiro((float)$it['preco_aplicado'])?>/un <?php if($o['status']==='aguardando_aprovacao'&&$it['cliente_aprovou']===null):?><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="acao" value="responder"><input type="hidden" name="item" value="<?=$it['id_item']?>"><button name="resposta" value="aprovar">Aprovar</button><button class="button secondary" name="resposta" value="recusar">Recusar</button></form><?php endif;?></p><?php endforeach;?><?php if($o['status']==='pendente'):?><form method="post" onsubmit="return confirm('Cancelar este pedido?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="acao" value="cancelar"><input type="hidden" name="pedido" value="<?=$o['id_pedido']?>"><button class="button secondary">Solicitar cancelamento</button></form><?php endif;?><?php if($o['modalidade_entrega']==='retirada'&&$o['status']==='pronto'):?><p class="notice success">Código de retirada: <strong><?=h($o['pin_entrega'])?></strong>. Apresente-o na loja para receber seu pedido.</p><?php elseif($o['modalidade_entrega']!=='retirada'&&$o['status']==='em_transito'):?><p>PIN de entrega: <strong><?=h($o['pin_entrega'])?></strong> (informe ao entregador ao receber).</p><?php endif;?></section><?php endforeach;?></main><?php if(($_GET['compra']??'')==='finalizada'):?><script>localStorage.removeItem('alvorada-cart');localStorage.removeItem('alvorada-delivery');</script><?php endif;?><script src="/assets/js/cep.js"></script><?php require __DIR__.'/../includes/site-footer.php'; ?>
</body></html>
